WITH filtered AS (SELECT *, UPPER(status) AS status_upper FROM shipments WHERE delivered_date > DATE '2023-08-05' AND order_id IS NOT NULL), remaining_keys AS (SELECT status, id FROM filtered INTERSECT ALL SELECT status, id FROM shipments WHERE status NOT IN ('DELIVERED', 'RETURNED')), kept_rows AS (SELECT s.* FROM filtered s INNER JOIN remaining_keys k ON s.status = k.status AND s.id = k.id), enriched AS (SELECT a.id, a.order_id, a.carrier, a.shipped_date, a.cost, a.status, p.order_date FROM kept_rows a LEFT JOIN orders p ON a.order_id <=> p.id), metrics AS (SELECT *, DENSE_RANK() OVER w_part AS cost_dense_rank, ROUND(cost / SUM(cost) OVER (PARTITION BY DATE_TRUNC('week', order_date)), 4) AS cost_share, DENSE_RANK() OVER (ORDER BY cost) AS cost_dense_rank_2, MAX(cost) OVER (PARTITION BY order_id) AS order_id_max_cost FROM enriched WINDOW w_part AS (PARTITION BY order_id ORDER BY cost)), cleaned AS (SELECT *, UPPER(status) AS status_upper FROM metrics WHERE order_id IS NOT NULL) SELECT id, carrier, shipped_date, cost, order_date, cost_dense_rank, order_id_max_cost, status_upper, CASE WHEN carrier RLIKE '^(Kerry|FedEx)$' THEN 'PRIORITY' ELSE 'CORE' END AS carrier_zone FROM cleaned ORDER BY cost;
